#!/bin/bash
# Nsight Compute breakdown of GEMM kernels on the homelab: tensor-pipe utilisation, shared-memory wavefronts/bank conflicts, L1/TEX throughput and the warp stall mix.
#   tools/ncu_gemm.sh <kernel-regex> [launch-skip]      e.g.  tools/ncu_gemm.sh '^gemm_nt_f32$' 4        (profiles launch #5 of the throughput test with that name)
# The reported SM clock is whatever ncu locked (base clocks unless --clock-control none is used here): compare kernels with each other, not with wall-clock TFLOPs.
KEY="$HOME/.ssh/id_ed25519"
HOST="user@homelab"
K="$1"; SKIP="${2:-4}"
M="gpu__time_duration.sum,sm__cycles_elapsed.avg.per_second,l1tex__throughput.avg.pct_of_peak_sustained_elapsed,l1tex__data_pipe_lsu_wavefronts_mem_shared.sum,l1tex__data_bank_conflicts_pipe_lsu_mem_shared.sum,sm__pipe_tensor_op_hmma_cycles_active.avg.pct_of_peak_sustained_active,smsp__inst_executed_op_ldsm.sum,smsp__inst_executed_op_shared_st.sum,smsp__inst_executed_op_global_ld.sum,smsp__inst_executed.sum,smsp__warps_active.avg.per_cycle_active,"
M+="smsp__warp_issue_stalled_barrier_per_warp_active.pct,smsp__warp_issue_stalled_long_scoreboard_per_warp_active.pct,smsp__warp_issue_stalled_short_scoreboard_per_warp_active.pct,smsp__warp_issue_stalled_mio_throttle_per_warp_active.pct,smsp__warp_issue_stalled_math_pipe_throttle_per_warp_active.pct,smsp__warp_issue_stalled_wait_per_warp_active.pct,smsp__warp_issue_stalled_lg_throttle_per_warp_active.pct,smsp__warp_issue_stalled_not_selected_per_warp_active.pct,smsp__warp_issue_stalled_selected_per_warp_active.pct,smsp__warp_issue_stalled_dispatch_stall_per_warp_active.pct,smsp__warp_issue_stalled_tex_throttle_per_warp_active.pct,smsp__warp_issue_stalled_no_instruction_per_warp_active.pct,smsp__warp_issue_stalled_membar_per_warp_active.pct,smsp__warp_issue_stalled_drain_per_warp_active.pct,smsp__warp_issue_stalled_branch_resolving_per_warp_active.pct"
exec ssh -i "$KEY" -o BatchMode=yes -o IdentitiesOnly=yes -o ConnectTimeout=10 "$HOST" "cd ~/forgeinfer/src; BIN=\$(ls -t target/release/deps/gemm-* | grep -v '\.d\$' | head -n 1); sudo -n \$HOME/cuda-13.2.0/bin/ncu ${NCU_EXTRA:-} --kernel-name regex:'$K' --launch-skip $SKIP --launch-count 1 --metrics $M \$BIN gemm_throughput --nocapture 2>&1 | grep -E 'gemm_|Duration|per_second|pct|\.sum|per_cycle' | grep -v 'GEMM '"
